INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000001b9',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss philosophy of mind at B2","Use Bewusstsein vocabulary","Talk about consciousness and identity"],"explanation":{"intro":"Philosophy of mind vocabulary covers consciousness, identity, and the mind-body problem at B2.","culturalNote":"Key concepts: das Leib-Seele-Problem (mind-body problem), Bewusstsein (consciousness), Qualia (subjective experience), Dualismus (dualism — Descartes), Materialismus (materialism), Funktionalismus (functionalism). German philosophers: Kant (transcendental idealism), Hegel (dialectics), Schopenhauer (will). Wittgenstein (Austrian-born, wrote in German) transformed philosophy of mind through Sprachspiele (language games)."},"examples":[{"german":"Das Leib-Seele-Problem fragt danach, wie mentale Zustände und physische Prozesse im Gehirn zusammenhängen.","english":"The mind-body problem asks how mental states and physical processes in the brain are connected."},{"german":"Ob Maschinen jemals echtes Bewusstsein entwickeln können, ist eine der drängendsten Fragen unserer Zeit.","english":"Whether machines can ever develop genuine consciousness is one of the most pressing questions of our time."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss philosophy of mind, consciousness, and the mind-body problem at B2."}}',
'{"items":[{"word":"das Bewusstsein","translation":"consciousness/awareness","pronunciation":"dahs beh-VOOST-zyn","example":"Echtes Bewusstsein."},{"word":"drängend","translation":"pressing/urgent","pronunciation":"DRENG-end","example":"Drängende Fragen."},{"word":"zusammenhängen","translation":"to be connected/related","pronunciation":"tsoo-ZAM-en-heng-en","example":"Wie sie zusammenhängen."},{"word":"der mentale Zustand","translation":"mental state","pronunciation":"dayr men-TAH-leh TSOOS-tant","example":"Mentale Zustände."},{"word":"entwickeln","translation":"to develop","pronunciation":"ent-VIK-eln","example":"Bewusstsein entwickeln."},{"word":"echt","translation":"genuine/real","pronunciation":"ekht","example":"Echtes Bewusstsein."}]}',
'{"title":"Danach fragen — to ask about / inquire into","pattern":"danach fragen, wie/ob/warum... = to ask about, inquire into (indirect question)","explanation":"Danach fragen, wie/ob/warum = to ask how/whether/why (indirect question construction). Das Problem fragt danach, wie X und Y zusammenhängen = The problem inquires into how X and Y are connected. The danach is a pronominal adverb standing in for the indirect question. Also: es geht darum, ob (it''s about whether), es kommt darauf an, wie (it depends on how). These constructions make abstract inquiry more precise at B2.","examples":[{"sentence":"Die Forschung fragt danach, warum manche Menschen resilienter sind.","translation":"The research asks why some people are more resilient."},{"sentence":"Es geht darum, ob die Theorie empirisch überprüfbar ist.","translation":"It is about whether the theory is empirically verifiable."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Drängend'' means?","options":["pressing/urgent","pushing","demanding","critical"],"correctAnswer":"pressing/urgent"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The mind-body problem asks how mental states and physical processes in the brain are connected.","options":["Das Leib-Seele-Problem fragt danach, wie mentale Zustände und physische Prozesse im Gehirn zusammenhängen.","Das Leib-Seele-Problem untersucht Gehirn und Geist.","Geist und Körper sind das Thema des Leib-Seele-Problems.","Mentale Zustände und Gehirnprozesse werden untersucht."],"correctAnswer":"Das Leib-Seele-Problem fragt danach, wie mentale Zustände und physische Prozesse im Gehirn zusammenhängen."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Die Forschung fragt danach, warum manche Menschen resilienter ___.","options":["sind","sein","werden","wären"],"correctAnswer":"sind"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: It is about whether the theory is empirically verifiable","wordBankItems":["Es","geht","darum",",","ob","die","Theorie","empirisch","überprüfbar","ist","."],"correctAnswer":"Es geht darum , ob die Theorie empirisch überprüfbar ist ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Das Bewusstsein'' means?","options":["consciousness/awareness","knowledge","understanding","perception"],"correctAnswer":"consciousness/awareness"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000001ba',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss epistemology at B2","Use Erkenntnistheorie vocabulary","Talk about knowledge and truth"],"explanation":{"intro":"Epistemology vocabulary covers the nature of knowledge, truth, and belief at B2.","culturalNote":"Erkenntnistheorie (epistemology) — central questions: Was ist Wissen? (What is knowledge?), Wie können wir Wahrheit erkennen? Key thinkers: Kant (Grenzen der Vernunft — limits of reason), Hegel (dialectical progress of knowledge), Nietzsche (perspectivism — no absolute truth), Popper (Falsifizierbarkeit — falsifiability). German idealism (Deutscher Idealismus) shaped all modern epistemology."},"examples":[{"german":"Erkenntnistheorie untersucht die Grundlagen, den Umfang und die Grenzen menschlichen Wissens.","english":"Epistemology examines the foundations, scope, and limits of human knowledge."},{"german":"Popper argumentierte, dass wissenschaftliche Theorien nicht verifiziert, sondern nur falsifiziert werden können.","english":"Popper argued that scientific theories cannot be verified, but only falsified."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss epistemology, knowledge, and scientific falsifiability at B2."}}',
'{"items":[{"word":"der Umfang","translation":"scope/extent","pronunciation":"dayr OOM-fang","example":"Der Umfang des Wissens."},{"word":"die Grundlage","translation":"foundation/basis","pronunciation":"dee GROONT-lah-geh","example":"Grundlagen des Wissens."},{"word":"verifizieren","translation":"to verify","pronunciation":"veh-ri-fi-TSEER-en","example":"Verifizieren."},{"word":"falsifizieren","translation":"to falsify","pronunciation":"fal-zi-fi-TSEER-en","example":"Falsifizieren."},{"word":"argumentieren","translation":"to argue (a position)","pronunciation":"ar-goo-men-TEER-en","example":"Popper argumentierte."},{"word":"die Grenze","translation":"limit/boundary","pronunciation":"dee GREN-tseh","example":"Grenzen des Wissens."}]}',
'{"title":"Nicht...sondern (nur) — not...but (only) — corrective","pattern":"nicht X, sondern (nur) Y = not X but (only) Y — one claim corrected by another","explanation":"Nicht...sondern = not X but Y (corrective — X is wrong, Y is right). Theorien können nicht verifiziert, sondern nur falsifiziert werden = Theories cannot be verified, but only falsified. The sondern corrects the nicht. Word order: nicht appears where X would normally be; sondern starts the correction. Common mistake: using aber instead of sondern. Aber = however (both can be true); Sondern = but rather (X is negated first).","examples":[{"sentence":"Das ist nicht ein Problem, sondern eine Chance.","translation":"That is not a problem, but an opportunity."},{"sentence":"Er wollte nicht fliehen, sondern kämpfen.","translation":"He did not want to flee, but to fight."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Der Umfang'' means?","options":["scope/extent","range","volume","circumference"],"correctAnswer":"scope/extent"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Popper argued that scientific theories cannot be verified, but only falsified.","options":["Popper argumentierte, dass wissenschaftliche Theorien nicht verifiziert, sondern nur falsifiziert werden können.","Popper sagte, man kann Theorien nicht beweisen.","Wissenschaftliche Theorien sind nur widerlegbar.","Popper unterschied Verifikation und Falsifikation."],"correctAnswer":"Popper argumentierte, dass wissenschaftliche Theorien nicht verifiziert, sondern nur falsifiziert werden können."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Das ist nicht ein Problem, ___ eine Chance.","options":["sondern","aber","doch","jedoch"],"correctAnswer":"sondern"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: He did not want to flee but to fight","wordBankItems":["Er","wollte","nicht","fliehen",",","sondern","kämpfen","."],"correctAnswer":"Er wollte nicht fliehen , sondern kämpfen ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Die Grundlage'' means?","options":["foundation/basis","ground","base","principle"],"correctAnswer":"foundation/basis"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000001bb',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss ethics at B2","Use Ethik vocabulary","Talk about moral frameworks"],"explanation":{"intro":"Ethics vocabulary covers moral theories, applied ethics, and normative frameworks at B2.","culturalNote":"Key ethical frameworks: Deontologie (deontology — Kant''s Pflichtethik / duty ethics), Utilitarismus (utilitarianism — greatest happiness), Tugendethik (virtue ethics — Aristotle), Diskursethik (discourse ethics — Habermas). Applied ethics: Bioethik (bioethics), Umweltethik (environmental ethics), Technikethik (ethics of technology). Der Ethikrat (German Ethics Council) advises on bioethical issues."},"examples":[{"german":"Kants kategorischer Imperativ verlangt, nur nach Maximen zu handeln, die man zugleich als allgemeines Gesetz wollen könnte.","english":"Kant''s categorical imperative demands acting only according to maxims one could simultaneously want as universal law."},{"german":"Im Utilitarismus wird eine Handlung als moralisch richtig bewertet, wenn sie den Gesamtnutzen maximiert.","english":"In utilitarianism, an action is evaluated as morally right if it maximises overall utility."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss ethical frameworks, Kant, and utilitarianism at B2."}}',
'{"items":[{"word":"der kategorische Imperativ","translation":"categorical imperative","pronunciation":"dayr kah-teh-GOH-rish-eh im-peh-rah-TEEF","example":"Kategorischer Imperativ."},{"word":"die Maxime","translation":"maxim","pronunciation":"dee mak-SEE-meh","example":"Nach Maximen handeln."},{"word":"zugleich","translation":"simultaneously/at the same time","pronunciation":"tsoo-GLYKH","example":"Zugleich wollen."},{"word":"der Gesamtnutzen","translation":"overall utility","pronunciation":"dayr geh-ZAHMT-noot-sen","example":"Gesamtnutzen maximieren."},{"word":"bewerten","translation":"to evaluate/assess","pronunciation":"beh-VER-ten","example":"Als richtig bewerten."},{"word":"maximieren","translation":"to maximise","pronunciation":"mak-si-MEER-en","example":"Nutzen maximieren."}]}',
'{"title":"Als...bewerten — to evaluate/rate as","pattern":"etwas als + adjective/noun bewerten = to evaluate/assess as, to rate as","explanation":"Bewerten als + accusative = to evaluate as, rate as, judge as. Eine Handlung als moralisch richtig bewerten = to evaluate an action as morally right. Passive: wird als X bewertet = is evaluated as X. Die Bewertung = evaluation, assessment, rating. Compare: beurteilen als (to judge as — slightly more personal judgment), einschätzen als (to estimate/assess as — often about future), betrachten als (to regard as — more permanent view).","examples":[{"sentence":"Das Projekt wurde als Erfolg bewertet.","translation":"The project was evaluated as a success."},{"sentence":"Man kann dieses Verhalten nicht als normal bewerten.","translation":"One cannot evaluate this behaviour as normal."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Maxime'' means?","options":["maxim","principle","rule","guideline"],"correctAnswer":"maxim"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"In utilitarianism, an action is evaluated as morally right if it maximises overall utility.","options":["Im Utilitarismus wird eine Handlung als moralisch richtig bewertet, wenn sie den Gesamtnutzen maximiert.","Utilitarismus bewertet Handlungen nach ihrem Nutzen.","Eine Handlung ist richtig, wenn sie den größten Nutzen bringt.","Moralische Handlungen maximieren den Gesamtnutzen."],"correctAnswer":"Im Utilitarismus wird eine Handlung als moralisch richtig bewertet, wenn sie den Gesamtnutzen maximiert."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Das Projekt wurde als Erfolg ___.","options":["bewertet","beurteilt","eingeschätzt","betrachtet"],"correctAnswer":"bewertet"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: One cannot evaluate this behaviour as normal","wordBankItems":["Man","kann","dieses","Verhalten","nicht","als","normal","bewerten","."],"correctAnswer":"Man kann dieses Verhalten nicht als normal bewerten ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Zugleich'' means?","options":["simultaneously/at the same time","at once","together","equally"],"correctAnswer":"simultaneously/at the same time"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000001bc',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss political philosophy at B2","Use politische Philosophie vocabulary","Talk about justice and legitimacy"],"explanation":{"intro":"Political philosophy vocabulary covers justice, rights, and legitimacy at B2.","culturalNote":"Key political philosophers discussed in Germany: Hobbes (Leviathan — social contract), Locke (Naturrechte — natural rights), Rousseau (Gemeinwille — general will), Rawls (Schleier des Nichtwissens — veil of ignorance), Habermas (deliberative democracy). Key concepts: Gerechtigkeit (justice), sozialer Kontrakt (social contract), Freiheit (freedom/liberty), Gleichheit (equality), Solidarität (solidarity)."},"examples":[{"german":"John Rawls schlug vor, Grundsätze der Gerechtigkeit hinter einem ''Schleier des Nichtwissens'' zu entwickeln.","english":"John Rawls proposed developing principles of justice behind a ''veil of ignorance''."},{"german":"Legitimation politischer Herrschaft setzt nach Habermas einen herrschaftsfreien Diskurs voraus.","english":"According to Habermas, the legitimation of political authority presupposes a discourse free from domination."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss political philosophy, justice, and legitimacy at B2."}}',
'{"items":[{"word":"der Grundsatz","translation":"principle/maxim","pronunciation":"dayr GROONT-zats","example":"Grundsätze der Gerechtigkeit."},{"word":"voraussetzen","translation":"to presuppose/require","pronunciation":"for-OWS-zetsen","example":"Etwas voraussetzen."},{"word":"herrschaftsfrei","translation":"free from domination","pronunciation":"HER-shaft-fry","example":"Herrschaftsfreier Diskurs."},{"word":"vorschlagen","translation":"to propose/suggest","pronunciation":"FOR-shlah-gen","example":"Vorschlagen."},{"word":"die Herrschaft","translation":"authority/domination","pronunciation":"dee HER-shaft","example":"Politische Herrschaft."},{"word":"die Legitimation","translation":"legitimation","pronunciation":"dee leh-gee-tee-mah-tsee-OHN","example":"Legitimation der Herrschaft."}]}',
'{"title":"Voraussetzen — to presuppose / require as a precondition","pattern":"etwas setzt X voraus (separable) = something presupposes/requires X as a precondition","explanation":"Voraussetzen (separable) = to presuppose, require as precondition. Legitimation setzt Diskurs voraus = Legitimation presupposes discourse. Perfect: hat vorausgesetzt. Die Voraussetzung = precondition, requirement. Also: die Grundvoraussetzung (fundamental precondition). In academic/formal German, voraussetzen marks a logical prerequisite — stronger than brauchen (to need) or erfordern (to require — more practical).","examples":[{"sentence":"Demokratie setzt eine informierte Bürgerschaft voraus.","translation":"Democracy presupposes an informed citizenry."},{"sentence":"Das Studium setzt das Abitur voraus.","translation":"The course of study requires the Abitur as a prerequisite."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Der Grundsatz'' means?","options":["principle/maxim","basis","foundation","rule"],"correctAnswer":"principle/maxim"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"According to Habermas, the legitimation of political authority presupposes a discourse free from domination.","options":["Legitimation politischer Herrschaft setzt nach Habermas einen herrschaftsfreien Diskurs voraus.","Habermas sagt, dass Legitimation Diskurs braucht.","Herrschaftsfreier Diskurs legitimiert politische Macht.","Habermas verlangt herrschaftsfreien Diskurs."],"correctAnswer":"Legitimation politischer Herrschaft setzt nach Habermas einen herrschaftsfreien Diskurs voraus."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Demokratie setzt eine informierte Bürgerschaft ___.","options":["voraus","vorher","vorher an","an"],"correctAnswer":"voraus"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The course of study requires the Abitur as a prerequisite","wordBankItems":["Das","Studium","setzt","das","Abitur","voraus","."],"correctAnswer":"Das Studium setzt das Abitur voraus ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Die Herrschaft'' means?","options":["authority/domination","rule","power","government"],"correctAnswer":"authority/domination"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000001bd',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss philosophy of science at B2","Use Wissenschaftstheorie vocabulary","Talk about paradigms and scientific progress"],"explanation":{"intro":"Philosophy of science vocabulary covers scientific method, paradigms, and progress at B2.","culturalNote":"Key concepts: Paradigmenwechsel (paradigm shift — Kuhn), Falsifizierbarkeit (falsifiability — Popper), induktives Schließen (inductive reasoning), deduktives Schließen (deductive reasoning), wissenschaftliche Revolution (scientific revolution). Germany''s tradition of Naturwissenschaften vs. Geisteswissenschaften (natural sciences vs. humanities) dates to the 19th century. Die DFG (Deutsche Forschungsgemeinschaft) funds German research."},"examples":[{"german":"Thomas Kuhns Konzept des Paradigmenwechsels beschreibt, wie sich wissenschaftliche Grundannahmen revolutionär verändern.","english":"Thomas Kuhn''s concept of the paradigm shift describes how the fundamental assumptions of science change in a revolutionary manner."},{"german":"Wissenschaftlicher Fortschritt verläuft selten linear, sondern wird durch Krisen, Anomalien und Neuorientierungen geprägt.","english":"Scientific progress rarely proceeds linearly, but is characterised by crises, anomalies, and reorientations."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss philosophy of science, paradigm shifts, and scientific progress at B2."}}',
'{"items":[{"word":"der Paradigmenwechsel","translation":"paradigm shift","pronunciation":"dayr pah-rah-DIG-men-vek-sel","example":"Paradigmenwechsel."},{"word":"die Grundannahme","translation":"fundamental assumption","pronunciation":"dee GROONT-an-nah-meh","example":"Wissenschaftliche Grundannahmen."},{"word":"linear","translation":"linear","pronunciation":"lee-neh-AR","example":"Linear verlaufen."},{"word":"die Anomalie","translation":"anomaly","pronunciation":"dee ah-noh-mah-LEE","example":"Anomalien."},{"word":"die Neuorientierung","translation":"reorientation","pronunciation":"dee NOY-or-ee-en-teer-oong","example":"Neuorientierungen."},{"word":"verlaufen","translation":"to proceed/run (of a process)","pronunciation":"fer-LOW-fen","example":"Linear verlaufen."}]}',
'{"title":"Verlaufen — to proceed, run, develop (of a process)","pattern":"etwas verläuft + adverb/adjective = something proceeds (a process unfolds in a certain way)","explanation":"Verlaufen = to proceed, run, unfold (used for processes — not physical movement). Der Prozess verläuft reibungslos = The process runs smoothly. Wissenschaftlicher Fortschritt verläuft selten linear = Scientific progress rarely proceeds linearly. Related: Der Verlauf = course, progression. Im Verlauf der Zeit = over the course of time. Im Verlauf des Gesprächs = in the course of the conversation. Compare: ablaufen (to run/expire — more about completion), stattfinden (to take place — events).","examples":[{"sentence":"Die Operation verlief komplikationslos.","translation":"The operation proceeded without complications."},{"sentence":"Die Verhandlungen verlaufen schleppend.","translation":"The negotiations are proceeding sluggishly."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Der Paradigmenwechsel'' means?","options":["paradigm shift","paradigm change","revolutionary shift","framework change"],"correctAnswer":"paradigm shift"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Scientific progress rarely proceeds linearly, but is characterised by crises, anomalies, and reorientations.","options":["Wissenschaftlicher Fortschritt verläuft selten linear, sondern wird durch Krisen, Anomalien und Neuorientierungen geprägt.","Wissenschaft macht keine linearen Fortschritte.","Wissenschaftliche Krisen und Anomalien prägen den Fortschritt.","Wissenschaftlicher Fortschritt ist nicht linear."],"correctAnswer":"Wissenschaftlicher Fortschritt verläuft selten linear, sondern wird durch Krisen, Anomalien und Neuorientierungen geprägt."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Die Operation verlief ___.","options":["komplikationslos","ohne Komplikationen verlief","problemlos verlief","reibungslos gewesen"],"correctAnswer":"komplikationslos"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The negotiations are proceeding sluggishly","wordBankItems":["Die","Verhandlungen","verlaufen","schleppend","."],"correctAnswer":"Die Verhandlungen verlaufen schleppend ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Die Grundannahme'' means?","options":["fundamental assumption","basic premise","underlying principle","core belief"],"correctAnswer":"fundamental assumption"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000001be',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss logic and argumentation at B2","Use Logik vocabulary","Construct valid arguments"],"explanation":{"intro":"Logic and argumentation vocabulary covers formal logic, fallacies, and valid reasoning at B2.","culturalNote":"Key concepts: deduktives vs. induktives Schließen (deductive vs. inductive reasoning), Syllogismus (syllogism), Trugschluss (fallacy), Ad-hominem-Argument, Strohmann-Argument (straw man), circuläres Argument (circular argument). In German academic discourse, Argumentation is highly valued — students are taught to write Erörterungen (argumentative essays) from early school age."},"examples":[{"german":"Ein gültiges Argument muss sowohl formal korrekt als auch inhaltlich wahr sein, um als schlüssig zu gelten.","english":"A valid argument must be both formally correct and true in content in order to be considered conclusive."},{"german":"Der Trugschluss des Ad-hominem greift die Person an, statt deren Argumente zu widerlegen.","english":"The ad hominem fallacy attacks the person rather than refuting their arguments."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss logic, argumentation, and fallacies at B2."}}',
'{"items":[{"word":"gültig","translation":"valid","pronunciation":"GÜL-tikh","example":"Gültiges Argument."},{"word":"schlüssig","translation":"conclusive/logical","pronunciation":"SHLÜ-sikh","example":"Als schlüssig gelten."},{"word":"widerlegen","translation":"to refute","pronunciation":"VEE-der-lay-gen","example":"Argumente widerlegen."},{"word":"der Trugschluss","translation":"fallacy","pronunciation":"dayr TROOK-shlooss","example":"Ein Trugschluss."},{"word":"inhaltlich","translation":"in content/regarding content","pronunciation":"IN-halt-likh","example":"Inhaltlich wahr."},{"word":"formal","translation":"formally","pronunciation":"for-MAHL","example":"Formal korrekt."}]}',
'{"title":"Als...gelten — to be considered/regarded as","pattern":"als + adjective/noun gelten = to be considered as, to count as, to be regarded as (general perception)","explanation":"Als X gelten = to be considered X, to pass for X, to count as X. Das gilt als Beweis = That counts as evidence. Sie gilt als Expertin = She is considered an expert. Gelten für = to apply to, be valid for. Das gilt auch für uns = That applies to us too. Compare: als...betrachtet werden (to be viewed as — passive, more deliberate perspective), als...angesehen werden (to be regarded as — passive, more formal), als...eingestuft werden (to be classified as — official/administrative).","examples":[{"sentence":"Das Verhalten gilt als grob fahrlässig.","translation":"The behaviour is considered grossly negligent."},{"sentence":"Diese Aussage gilt als Beweis für seine Unschuld.","translation":"This statement counts as evidence of his innocence."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Schlüssig'' means?","options":["conclusive/logical","closed","coherent","convincing"],"correctAnswer":"conclusive/logical"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"A valid argument must be both formally correct and true in content in order to be considered conclusive.","options":["Ein gültiges Argument muss sowohl formal korrekt als auch inhaltlich wahr sein, um als schlüssig zu gelten.","Ein Argument ist gültig, wenn es richtig und wahr ist.","Gute Argumente sind formal und inhaltlich korrekt.","Ein schlüssiges Argument ist formal korrekt."],"correctAnswer":"Ein gültiges Argument muss sowohl formal korrekt als auch inhaltlich wahr sein, um als schlüssig zu gelten."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Das Verhalten gilt als grob ___.","options":["fahrlässig","fahrlässig gilt","fahrlässigen","fahrlässig sein"],"correctAnswer":"fahrlässig"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: This statement counts as evidence of his innocence","wordBankItems":["Diese","Aussage","gilt","als","Beweis","für","seine","Unschuld","."],"correctAnswer":"Diese Aussage gilt als Beweis für seine Unschuld ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Widerlegen'' means?","options":["to refute","to contradict","to disprove","to deny"],"correctAnswer":"to refute"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000001bf',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss philosophy of language at B2","Use Sprachphilosophie vocabulary","Talk about meaning and communication"],"explanation":{"intro":"Philosophy of language vocabulary covers meaning, reference, and communication at B2.","culturalNote":"Key concepts: die Bedeutung (meaning), der Referent (referent), die Pragmatik (pragmatics), Sprechakte (speech acts — Austin/Searle), Sprachspiele (language games — Wittgenstein), Semiotik (semiotics). Wittgenstein: ''Die Grenzen meiner Sprache bedeuten die Grenzen meiner Welt'' (The limits of my language mean the limits of my world). Key: language shapes thought (Sapir-Whorf hypothesis)."},"examples":[{"german":"Wittgenstein zufolge ist die Bedeutung eines Wortes sein Gebrauch in der Sprache.","english":"According to Wittgenstein, the meaning of a word is its use in language."},{"german":"Sprechakte sind Äußerungen, die nicht nur etwas beschreiben, sondern auch eine Handlung vollziehen.","english":"Speech acts are utterances that do not merely describe something but also perform an action."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss philosophy of language, meaning, and speech acts at B2."}}',
'{"items":[{"word":"die Äußerung","translation":"utterance/statement","pronunciation":"dee OY-seh-roong","example":"Eine Äußerung machen."},{"word":"vollziehen","translation":"to perform/execute","pronunciation":"fol-TSEE-en","example":"Eine Handlung vollziehen."},{"word":"der Gebrauch","translation":"use/usage","pronunciation":"dayr geh-BROWKH","example":"Gebrauch eines Wortes."},{"word":"zufolge","translation":"according to","pronunciation":"tsoo-FOL-geh","example":"Wittgenstein zufolge."},{"word":"die Pragmatik","translation":"pragmatics","pronunciation":"dee prag-MAH-tik","example":"Linguistische Pragmatik."},{"word":"beschreiben","translation":"to describe","pronunciation":"beh-SHRY-ben","example":"Etwas beschreiben."}]}',
'{"title":"Zufolge — according to (follows the noun)","pattern":"[noun/name] + zufolge = according to (postposition — comes after the dative noun)","explanation":"Zufolge = according to. Unlike nach (preposition — before the noun), zufolge is a POSTPOSITION — it follows the noun in dative. Wittgenstein zufolge = according to Wittgenstein. Also: Berichten zufolge = according to reports. Die Aussage zufolge = according to the statement. Compare: nach (Nach Berichten = according to reports — more colloquial), laut (Laut Berichten = according to reports — often with genitive, journalistic), gemäß (gemäß den Berichten = in accordance with — formal/legal).","examples":[{"sentence":"Studien zufolge steigt die Lebenserwartung weiter.","translation":"According to studies, life expectancy continues to rise."},{"sentence":"Dem Bericht zufolge gibt es keine Hinweise auf Unregelmäßigkeiten.","translation":"According to the report, there are no indications of irregularities."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Äußerung'' means?","options":["utterance/statement","expression","remark","comment"],"correctAnswer":"utterance/statement"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"According to Wittgenstein, the meaning of a word is its use in language.","options":["Wittgenstein zufolge ist die Bedeutung eines Wortes sein Gebrauch in der Sprache.","Wittgenstein sagt, Bedeutung kommt durch Gebrauch.","Nach Wittgenstein entsteht Bedeutung durch Sprachgebrauch.","Wittgenstein meint, Sprache bestimmt Bedeutung."],"correctAnswer":"Wittgenstein zufolge ist die Bedeutung eines Wortes sein Gebrauch in der Sprache."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Studien ___ steigt die Lebenserwartung weiter.","options":["zufolge","nach","laut","gemäß"],"correctAnswer":"zufolge"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: According to the report there are no indications of irregularities","wordBankItems":["Dem","Bericht","zufolge","gibt","es","keine","Hinweise","auf","Unregelmäßigkeiten","."],"correctAnswer":"Dem Bericht zufolge gibt es keine Hinweise auf Unregelmäßigkeiten ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Vollziehen'' means?","options":["to perform/execute","to complete","to carry out","to enact"],"correctAnswer":"to perform/execute"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000001c0',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss aesthetics at B2","Use Ästhetik vocabulary","Talk about art theory and beauty"],"explanation":{"intro":"Aesthetics vocabulary covers the philosophy of art, beauty, and taste at B2.","culturalNote":"Key concepts: das Erhabene (the sublime — Kant), das Schöne (the beautiful), die ästhetische Erfahrung (aesthetic experience), Kunstkritik (art criticism), das Kunstwerk (artwork). Key German aestheticians: Kant (Kritik der Urteilskraft), Hegel (Vorlesungen über Ästhetik), Adorno (Ästhetische Theorie — critical theory and art). Die Documenta (Kassel) is one of the world''s most important contemporary art exhibitions."},"examples":[{"german":"Kant unterschied zwischen dem Schönen und dem Erhabenen: Das Schöne erfreut, das Erhabene überwältigt.","english":"Kant distinguished between the beautiful and the sublime: the beautiful delights, the sublime overwhelms."},{"german":"Ästhetische Urteile beanspruchen universelle Gültigkeit, obwohl sie auf subjektivem Geschmack beruhen.","english":"Aesthetic judgements claim universal validity, although they rest on subjective taste."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss aesthetics, beauty, the sublime, and art theory at B2."}}',
'{"items":[{"word":"das Erhabene","translation":"the sublime","pronunciation":"dahs er-HAH-beh-neh","example":"Das Erhabene bei Kant."},{"word":"überwältigen","translation":"to overwhelm","pronunciation":"ü-ber-VEL-tee-gen","example":"Überwältigt werden."},{"word":"erfreuen","translation":"to delight/please","pronunciation":"er-FROY-en","example":"Das Schöne erfreut."},{"word":"die Gültigkeit","translation":"validity","pronunciation":"dee GÜL-tikh-kyt","example":"Universelle Gültigkeit."},{"word":"das Urteil","translation":"judgement","pronunciation":"dahs OOR-tyl","example":"Ästhetisches Urteil."},{"word":"beruhen auf","translation":"to rest on/be based on","pronunciation":"beh-ROO-en owf","example":"Auf Geschmack beruhen."}]}',
'{"title":"Beruhen auf — to rest on, be based on","pattern":"etwas beruht auf + dative = something rests on, is based on (state — not action)","explanation":"Beruhen auf + dative = to rest on, to be based on (static relationship). Ästhetische Urteile beruhen auf Geschmack = Aesthetic judgements rest on taste. Compare: basieren auf (to be based on — more modern/common, also used with dative), gründen auf (to be founded on — historical, architectural); sich stützen auf + accusative (to lean/rely on — more active). Beruhen auf is more formal/literary than basieren auf.","examples":[{"sentence":"Die Theorie beruht auf empirischen Beobachtungen.","translation":"The theory rests on empirical observations."},{"sentence":"Ihr Vertrauen beruht auf langjähriger Erfahrung.","translation":"Her trust rests on many years of experience."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Das Erhabene'' means?","options":["the sublime","the exalted","the elevated","the superior"],"correctAnswer":"the sublime"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Aesthetic judgements claim universal validity, although they rest on subjective taste.","options":["Ästhetische Urteile beanspruchen universelle Gültigkeit, obwohl sie auf subjektivem Geschmack beruhen.","Ästhetische Urteile sind subjektiv, aber beanspruchen Allgemeingültigkeit.","Obwohl Geschmack subjektiv ist, beanspruchen ästhetische Urteile Gültigkeit.","Ästhetik verbindet Subjektivität mit universellem Anspruch."],"correctAnswer":"Ästhetische Urteile beanspruchen universelle Gültigkeit, obwohl sie auf subjektivem Geschmack beruhen."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Die Theorie beruht auf empirischen ___.","options":["Beobachtungen","Daten","Fakten","Forschungen"],"correctAnswer":"Beobachtungen"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Her trust rests on many years of experience","wordBankItems":["Ihr","Vertrauen","beruht","auf","langjähriger","Erfahrung","."],"correctAnswer":"Ihr Vertrauen beruht auf langjähriger Erfahrung ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Überwältigen'' means?","options":["to overwhelm","to overcome","to overpower","to dominate"],"correctAnswer":"to overwhelm"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000001c1',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss philosophy of culture at B2","Use Kulturphilosophie vocabulary","Talk about culture and identity"],"explanation":{"intro":"Philosophy of culture vocabulary covers cultural identity, diversity, and intercultural dialogue at B2.","culturalNote":"Key concepts: Kulturdefinition (culture definition — narrow vs. broad), Leitkultur (dominant culture — controversial concept), Multikulturalismus (multiculturalism), interkultureller Dialog (intercultural dialogue). Key thinkers: Herder (cultural pluralism), Cassirer (Symbolisches Tier — symbolic animal). Germany debates Leitkultur vs. Willkommenskultur (culture of welcome). UNESCO Konvention über kulturelle Vielfalt (2005)."},"examples":[{"german":"Kulturelle Identität ist kein statisches Erbe, sondern ein dynamischer Prozess der Auseinandersetzung und Neugestaltung.","english":"Cultural identity is not a static heritage, but a dynamic process of negotiation and reshaping."},{"german":"Interkultureller Dialog setzt die Bereitschaft voraus, die eigene Perspektive zu hinterfragen und andere Sichtweisen anzuerkennen.","english":"Intercultural dialogue presupposes the willingness to question one''s own perspective and to acknowledge other viewpoints."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss cultural identity, intercultural dialogue, and cultural philosophy at B2."}}',
'{"items":[{"word":"statisch","translation":"static","pronunciation":"SHTAH-tish","example":"Statisches Erbe."},{"word":"das Erbe","translation":"heritage/legacy","pronunciation":"dahs ER-beh","example":"Kulturelles Erbe."},{"word":"die Auseinandersetzung","translation":"negotiation/engagement/confrontation","pronunciation":"dee OWS-yn-an-der-zetsoong","example":"Auseinandersetzung."},{"word":"hinterfragen","translation":"to question/challenge","pronunciation":"HIN-ter-frah-gen","example":"Die eigene Perspektive hinterfragen."},{"word":"anerkennen","translation":"to acknowledge/recognise","pronunciation":"AN-er-ken-en","example":"Sichtweisen anerkennen."},{"word":"die Sichtweise","translation":"viewpoint/perspective","pronunciation":"dee ZIKHT-vy-zeh","example":"Andere Sichtweisen."}]}',
'{"title":"Hinterfragen — to question / interrogate critically","pattern":"etwas hinterfragen = to question critically, to interrogate (not just ask — implies critique)","explanation":"Hinterfragen = to question, examine critically, interrogate (not just ask a question — it implies critical scrutiny). Die eigene Perspektive hinterfragen = to question one''s own perspective. Hinterfrage das! = Question that! Unlike fragen (to ask), hinterfragen always implies critical examination or challenging assumptions. Perfect: hat hinterfragt. Compare: in Frage stellen (to call into question — similar but stronger, implying potential rejection), bezweifeln (to doubt — more emotional), kritisieren (to criticise — more direct).","examples":[{"sentence":"Man sollte gesellschaftliche Normen regelmäßig hinterfragen.","translation":"One should regularly question social norms."},{"sentence":"Die Studie hinterfragt die gängigen Annahmen über Produktivität.","translation":"The study questions the prevailing assumptions about productivity."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Statisch'' means?","options":["static","stable","fixed","unchanging"],"correctAnswer":"static"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Intercultural dialogue presupposes the willingness to question one''s own perspective and to acknowledge other viewpoints.","options":["Interkultureller Dialog setzt die Bereitschaft voraus, die eigene Perspektive zu hinterfragen und andere Sichtweisen anzuerkennen.","Interkultureller Dialog braucht Offenheit für andere Kulturen.","Man muss bereit sein, andere Perspektiven anzuerkennen.","Intercultural dialog setzt Offenheit und Respekt voraus."],"correctAnswer":"Interkultureller Dialog setzt die Bereitschaft voraus, die eigene Perspektive zu hinterfragen und andere Sichtweisen anzuerkennen."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Man sollte gesellschaftliche Normen regelmäßig ___.","options":["hinterfragen","fragen","befragen","anfragen"],"correctAnswer":"hinterfragen"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The study questions the prevailing assumptions about productivity","wordBankItems":["Die","Studie","hinterfragt","die","gängigen","Annahmen","über","Produktivität","."],"correctAnswer":"Die Studie hinterfragt die gängigen Annahmen über Produktivität ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Die Auseinandersetzung'' means?","options":["negotiation/engagement/confrontation","dispute","argument","examination"],"correctAnswer":"negotiation/engagement/confrontation"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000001c2',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss legal philosophy at B2","Use Rechtsphilosophie vocabulary","Talk about justice and natural law"],"explanation":{"intro":"Legal philosophy vocabulary covers natural law, positivism, and justice at B2.","culturalNote":"Key concepts: Naturrecht (natural law — rights derived from nature/reason), Rechtspositivismus (legal positivism — law is what the state enacts), Rechtsstaat (constitutional state — rule of law), Gerechtigkeit (justice). Key thinkers: Kant (Rechtsmetaphysik), Hart (legal positivism), Fuller (internal morality of law). Germany''s Grundgesetz was consciously designed to align with natural law principles after the Nazi experience."},"examples":[{"german":"Der Rechtspositivismus unterscheidet scharf zwischen dem Recht, wie es ist, und dem Recht, wie es sein sollte.","english":"Legal positivism sharply distinguishes between the law as it is and the law as it ought to be."},{"german":"Das Konzept des Rechtsstaats bindet staatliches Handeln an das Recht und schützt Bürger vor Willkür.","english":"The concept of the constitutional state binds governmental action to the law and protects citizens from arbitrariness."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss legal philosophy, natural law, and the rule of law at B2."}}',
'{"items":[{"word":"die Willkür","translation":"arbitrariness","pronunciation":"dee VIL-kür","example":"Schutz vor Willkür."},{"word":"binden an","translation":"to bind to/commit to","pronunciation":"BIN-den an","example":"An das Recht binden."},{"word":"scharf","translation":"sharply/clearly (of distinctions)","pronunciation":"sharf","example":"Scharf unterscheiden."},{"word":"staatlich","translation":"governmental/state","pronunciation":"SHTAHT-likh","example":"Staatliches Handeln."},{"word":"unterscheiden","translation":"to distinguish","pronunciation":"oon-ter-SHYD-en","example":"Scharf unterscheiden."},{"word":"das Naturrecht","translation":"natural law","pronunciation":"dahs nah-TOOR-rekht","example":"Naturrecht."}]}',
'{"title":"Binden an — to bind to, commit to","pattern":"jemanden/etwas an + accusative binden = to bind, commit, tie (to a rule, obligation, or standard)","explanation":"Binden an + accusative = to bind to, commit to. Das Recht bindet staatliches Handeln = Law binds governmental action. Sich an etwas gebunden fühlen = to feel bound by something. Gebunden an + accusative (adjective) = bound by. Common in legal and formal contexts. Also: an Regeln gebunden sein (to be bound by rules), an einen Auftrag gebunden sein (to be committed to a mandate). Compare: verpflichten zu (to oblige to — more personal obligation), festlegen auf (to commit to/pin down — more concrete action).","examples":[{"sentence":"Das Gericht ist an die geltende Rechtslage gebunden.","translation":"The court is bound by the current legal situation."},{"sentence":"Wir sind an unsere Zusagen gebunden.","translation":"We are bound by our commitments."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Willkür'' means?","options":["arbitrariness","willfulness","randomness","caprice"],"correctAnswer":"arbitrariness"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Legal positivism sharply distinguishes between the law as it is and the law as it ought to be.","options":["Der Rechtspositivismus unterscheidet scharf zwischen dem Recht, wie es ist, und dem Recht, wie es sein sollte.","Rechtspositivismus trennt Recht von Moral.","Positives Recht und Naturrecht sind verschieden.","Rechtspositivismus lehnt Naturrecht ab."],"correctAnswer":"Der Rechtspositivismus unterscheidet scharf zwischen dem Recht, wie es ist, und dem Recht, wie es sein sollte."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Das Gericht ist an die geltende Rechtslage ___.","options":["gebunden","verpflichtet","festgelegt","unterworfen"],"correctAnswer":"gebunden"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: We are bound by our commitments","wordBankItems":["Wir","sind","an","unsere","Zusagen","gebunden","."],"correctAnswer":"Wir sind an unsere Zusagen gebunden ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Staatlich'' means?","options":["governmental/state","public","national","official"],"correctAnswer":"governmental/state"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000001c3',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss financial markets at B2","Use Finanzmarkt vocabulary","Talk about stocks and capital markets"],"explanation":{"intro":"Financial markets vocabulary covers stocks, bonds, and capital markets at B2.","culturalNote":"Germany''s Finanzmarkt: Deutsche Börse (Frankfurt Stock Exchange — DAX, MDAX), Bundesanleihen (federal bonds — safe haven), Europäische Zentralbank (ECB — Frankfurt). Key concepts: Aktie (share/stock), Anleihe (bond), Investmentfonds (investment fund), Risikostreuung (diversification), Dividende (dividend), Kurs (price/rate). Germany has a Sparkultur but relatively low stock ownership compared to Anglo-Saxon countries."},"examples":[{"german":"Kapitalmärkte ermöglichen Unternehmen, Eigenkapital durch die Ausgabe von Aktien aufzunehmen.","english":"Capital markets enable companies to raise equity capital by issuing shares."},{"german":"Eine breite Risikostreuung gilt als wirksamste Strategie, um Verluste in volatilen Märkten zu minimieren.","english":"Broad diversification is regarded as the most effective strategy to minimise losses in volatile markets."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss financial markets, stocks, and capital markets at B2."}}',
'{"items":[{"word":"das Eigenkapital","translation":"equity capital","pronunciation":"dahs EY-gen-kah-pee-tahl","example":"Eigenkapital aufnehmen."},{"word":"aufnehmen","translation":"to raise (capital)/to take up","pronunciation":"OWF-nay-men","example":"Kapital aufnehmen."},{"word":"die Risikostreuung","translation":"diversification","pronunciation":"dee REE-zi-koh-shtroy-oong","example":"Risikostreuung."},{"word":"volatil","translation":"volatile","pronunciation":"voh-lah-TEEL","example":"Volatile Märkte."},{"word":"minimieren","translation":"to minimise","pronunciation":"mi-ni-MEER-en","example":"Verluste minimieren."},{"word":"die Ausgabe","translation":"issuance/issue","pronunciation":"dee OWS-gah-beh","example":"Ausgabe von Aktien."}]}',
'{"title":"Durch die Ausgabe von — by issuing / through the issuance of","pattern":"durch die Ausgabe von + noun = by issuing (process noun — action turned into a noun phrase)","explanation":"Durch + die + action-noun + von = by means of issuing/distributing. Durch die Ausgabe von Aktien = by issuing shares. This nominalised construction is very common in formal business and legal German. The action (ausgeben = to issue) becomes a noun (die Ausgabe = the issuance). This is the Nominalstil (nominal style) that B2+ learners must master. Compare: indem sie Aktien ausgeben (by issuing — verbal, mehr journalistisch). Nominalstil is the default in contracts, policy documents, and academic writing.","examples":[{"sentence":"Durch die Erhöhung der Zinssätze soll die Inflation gebremst werden.","translation":"By raising interest rates, inflation is to be curbed."},{"sentence":"Durch die Einführung neuer Technologien entstehen neue Berufsfelder.","translation":"Through the introduction of new technologies, new professional fields emerge."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Das Eigenkapital'' means?","options":["equity capital","own capital","private capital","shareholder capital"],"correctAnswer":"equity capital"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Capital markets enable companies to raise equity capital by issuing shares.","options":["Kapitalmärkte ermöglichen Unternehmen, Eigenkapital durch die Ausgabe von Aktien aufzunehmen.","Unternehmen können an der Börse Kapital beschaffen.","Durch Aktienausgabe können Unternehmen Kapital aufnehmen.","Kapitalmärkte finanzieren Unternehmen."],"correctAnswer":"Kapitalmärkte ermöglichen Unternehmen, Eigenkapital durch die Ausgabe von Aktien aufzunehmen."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Durch die Erhöhung der Zinssätze soll die Inflation ___ werden.","options":["gebremst","gesenkt","reduziert","gemindert"],"correctAnswer":"gebremst"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Through the introduction of new technologies new professional fields emerge","wordBankItems":["Durch","die","Einführung","neuer","Technologien","entstehen","neue","Berufsfelder","."],"correctAnswer":"Durch die Einführung neuer Technologien entstehen neue Berufsfelder ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Volatil'' means?","options":["volatile","unstable","fluctuating","variable"],"correctAnswer":"volatile"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000001c4',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss investments at B2","Use Investitionen vocabulary","Talk about returns and risk"],"explanation":{"intro":"Investment vocabulary covers returns, risk management, and investment strategies at B2.","culturalNote":"Key investment concepts: Rendite (return/yield), Risiko-Rendite-Profil (risk-return profile), Portfolio, ETF (Indexfonds — Exchange Traded Fund), Hedging, Liquidität (liquidity). German pension system relies heavily on Umlagesystem (pay-as-you-go). Private Altersvorsorge (private pension provision) increasingly important — Riester-Rente (state-subsidised private pension) widely used."},"examples":[{"german":"Jede Anlageentscheidung erfordert eine sorgfältige Abwägung von erwartetem Ertrag und eingegangenen Risiken.","english":"Every investment decision requires a careful weighing of expected return and risks taken on."},{"german":"Langfristige Investitionen in breit gestreute Indexfonds gelten als effiziente Strategie zur Altersvorsorge.","english":"Long-term investments in broadly diversified index funds are regarded as an efficient strategy for retirement provision."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss investments, returns, and risk management at B2."}}',
'{"items":[{"word":"die Abwägung","translation":"weighing/balancing","pronunciation":"dee AP-vä-goong","example":"Sorgfältige Abwägung."},{"word":"sorgfältig","translation":"careful/thorough","pronunciation":"ZORK-fel-tikh","example":"Sorgfältige Analyse."},{"word":"die Rendite","translation":"return/yield","pronunciation":"dee ren-DEE-teh","example":"Erwartete Rendite."},{"word":"eingehen","translation":"to take on (risk)/to enter into","pronunciation":"YN-gay-en","example":"Risiken eingehen."},{"word":"gestreut","translation":"diversified","pronunciation":"geh-SHTROYT","example":"Breit gestreut."},{"word":"die Altersvorsorge","translation":"retirement provision","pronunciation":"dee AL-ters-for-zor-geh","example":"Private Altersvorsorge."}]}',
'{"title":"Eingehen auf vs. Risiken eingehen — two meanings of eingehen","pattern":"Risiken eingehen = to take on risks; auf etwas eingehen = to address/respond to something","explanation":"Eingehen has two key uses: (1) Risiken eingehen = to take on risks, enter into commitments (eingehen auf/in for obligations). (2) Auf etwas eingehen = to respond to, address, engage with. Auf die Frage eingehen = to address the question. Das gehe ich nicht ein = I won''t engage with that / I won''t take on that. In business context: einen Kompromiss eingehen (to strike a compromise), eine Wette eingehen (to make a bet). Perfect: hat eingegangen. Die Eingehung = entering into (formal noun).","examples":[{"sentence":"Ich werde auf Ihre Kritik detailliert eingehen.","translation":"I will address your criticism in detail."},{"sentence":"Wir dürfen keine unnötigen Risiken eingehen.","translation":"We must not take on unnecessary risks."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Abwägung'' means?","options":["weighing/balancing","consideration","assessment","evaluation"],"correctAnswer":"weighing/balancing"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Every investment decision requires a careful weighing of expected return and risks taken on.","options":["Jede Anlageentscheidung erfordert eine sorgfältige Abwägung von erwartetem Ertrag und eingegangenen Risiken.","Investitionen müssen Risiken und Erträge abwägen.","Anleger müssen Risiko und Rendite sorgfältig analysieren.","Jede Investition ist mit Risiken verbunden."],"correctAnswer":"Jede Anlageentscheidung erfordert eine sorgfältige Abwägung von erwartetem Ertrag und eingegangenen Risiken."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Ich werde auf Ihre Kritik detailliert ___.","options":["eingehen","eingehend","eingegangen","einzugehen"],"correctAnswer":"eingehen"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: We must not take on unnecessary risks","wordBankItems":["Wir","dürfen","keine","unnötigen","Risiken","eingehen","."],"correctAnswer":"Wir dürfen keine unnötigen Risiken eingehen ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Die Rendite'' means?","options":["return/yield","profit","gain","interest"],"correctAnswer":"return/yield"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000001c5',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss macroeconomics at B2","Use Makroökonomie vocabulary","Talk about GDP, inflation, and cycles"],"explanation":{"intro":"Macroeconomics vocabulary covers national income, cycles, and economic policy at B2.","culturalNote":"Key macroeconomic concepts: Bruttoinlandsprodukt (BIP — GDP), Inflation, Deflation, Rezession (recession), Konjunktur (business cycle), Geldpolitik (monetary policy — ECB), Fiskalpolitik (fiscal policy — government), Arbeitslosigkeit (unemployment). Germany has historically been very focused on Preisstabilität (price stability — Bundesbank tradition)."},"examples":[{"german":"Inflation bezeichnet den allgemeinen Anstieg des Preisniveaus, der die Kaufkraft des Geldes schleichend untergräbt.","english":"Inflation denotes the general rise in the price level, which insidiously undermines the purchasing power of money."},{"german":"In einer Rezession schrumpft das Bruttoinlandsprodukt für mindestens zwei aufeinanderfolgende Quartale.","english":"In a recession, gross domestic product shrinks for at least two consecutive quarters."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss macroeconomics, inflation, and economic cycles at B2."}}',
'{"items":[{"word":"untergraben","translation":"to undermine","pronunciation":"oon-ter-GRAH-ben","example":"Die Kaufkraft untergraben."},{"word":"schleichend","translation":"insidiously/gradually/creeping","pronunciation":"SHLY-khend","example":"Schleichend untergraben."},{"word":"die Kaufkraft","translation":"purchasing power","pronunciation":"dee KOWF-kraft","example":"Kaufkraft des Geldes."},{"word":"aufeinanderfolgend","translation":"consecutive","pronunciation":"owf-yn-AN-der-fol-gend","example":"Aufeinanderfolgende Quartale."},{"word":"schrumpfen","translation":"to shrink","pronunciation":"SHROOMPF-en","example":"Das BIP schrumpft."},{"word":"das Bruttoinlandsprodukt","translation":"gross domestic product","pronunciation":"dahs BROO-toh-in-lands-pro-dookt","example":"BIP."}]}',
'{"title":"Schleichend — creeping/insidious (gradual negative process)","pattern":"schleichend + verb/adjective = insidiously, creepingly (slow, unnoticed negative process)","explanation":"Schleichend = creeping, insidious (describes a process that happens slowly and unnoticed, usually negatively). Schleichende Inflation = creeping inflation. Die Inflation untergräbt die Kaufkraft schleichend = Inflation insidiously undermines purchasing power. The key connotation: slow + unnoticed + harmful. Schleichen = to creep, sneak (movement verb). Related: der Schleichpfad (back-alley path), einschleichen (to creep in/sneak in). Often used in political/economic analysis to dramatise slow-moving problems.","examples":[{"sentence":"Die Qualität der Infrastruktur verschlechtert sich schleichend.","translation":"The quality of infrastructure is deteriorating insidiously."},{"sentence":"Schleichende Überwachung gefährdet die bürgerlichen Freiheiten.","translation":"Creeping surveillance endangers civil liberties."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Schleichend'' means?","options":["insidiously/gradually/creeping","slowly","stealthily","subtly"],"correctAnswer":"insidiously/gradually/creeping"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Inflation denotes the general rise in the price level, which insidiously undermines the purchasing power of money.","options":["Inflation bezeichnet den allgemeinen Anstieg des Preisniveaus, der die Kaufkraft des Geldes schleichend untergräbt.","Inflation bedeutet steigende Preise und sinkende Kaufkraft.","Durch Inflation sinkt die Kaufkraft des Geldes.","Inflation untergräbt die Kaufkraft."],"correctAnswer":"Inflation bezeichnet den allgemeinen Anstieg des Preisniveaus, der die Kaufkraft des Geldes schleichend untergräbt."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Die Qualität der Infrastruktur verschlechtert sich ___.","options":["schleichend","langsam","zunehmend","stetig"],"correctAnswer":"schleichend"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Creeping surveillance endangers civil liberties","wordBankItems":["Schleichende","Überwachung","gefährdet","die","bürgerlichen","Freiheiten","."],"correctAnswer":"Schleichende Überwachung gefährdet die bürgerlichen Freiheiten ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Aufeinanderfolgend'' means?","options":["consecutive","successive","sequential","following"],"correctAnswer":"consecutive"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000001c6',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss microeconomics at B2","Use Mikroökonomie vocabulary","Talk about supply, demand, and market failure"],"explanation":{"intro":"Microeconomics vocabulary covers individual markets, supply and demand, and market failure at B2.","culturalNote":"Key microeconomic concepts: Angebot und Nachfrage (supply and demand), Marktversagen (market failure), externe Effekte (externalities — positive/negative), öffentliche Güter (public goods), Monopol (monopoly), Oligopol (oligopoly), Kartell (cartel — illegal in Germany, Bundeskartellamt monitors). German Ordoliberalismus (ordoliberalism — social market economy) tries to prevent market failure through intelligent regulation."},"examples":[{"german":"Negative externe Effekte entstehen, wenn die Kosten einer wirtschaftlichen Aktivität auf unbeteiligte Dritte abgewälzt werden.","english":"Negative externalities arise when the costs of an economic activity are shifted onto uninvolved third parties."},{"german":"Öffentliche Güter sind nicht-rival und nicht-ausschließbar, was zu Marktversagen und Unterversorgung führt.","english":"Public goods are non-rival and non-excludable, which leads to market failure and undersupply."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss microeconomics, externalities, and market failure at B2."}}',
'{"items":[{"word":"der externe Effekt","translation":"externality","pronunciation":"dayr eks-TER-neh eh-FEKT","example":"Negative externe Effekte."},{"word":"abwälzen auf","translation":"to shift onto","pronunciation":"AP-vel-tsen owf","example":"Kosten abwälzen."},{"word":"unbeteiligt","translation":"uninvolved","pronunciation":"OON-beh-ty-likt","example":"Unbeteiligte Dritte."},{"word":"nicht-rival","translation":"non-rival","pronunciation":"nikht-ree-VAHL","example":"Nicht-rivales Gut."},{"word":"die Unterversorgung","translation":"undersupply","pronunciation":"dee OON-ter-fer-zor-goong","example":"Unterversorgung."},{"word":"ausschließbar","translation":"excludable","pronunciation":"OWS-shlees-bar","example":"Ausschließbar."}]}',
'{"title":"Abwälzen auf — to shift/offload onto","pattern":"etwas auf + accusative abwälzen = to shift, offload, pass on (costs, blame, responsibility)","explanation":"Abwälzen auf + accusative = to shift, offload, pass on. Kosten auf Dritte abwälzen = to shift costs onto third parties. Verantwortung abwälzen = to offload responsibility. Perfect: hat abgewälzt. The idiom carries a negative connotation — it is unfair or irresponsible offloading. Compare: übertragen auf (to transfer to — neutral), weitergeben an (to pass on to — neutral, often information), auslagern (to outsource — more technical).","examples":[{"sentence":"Das Unternehmen wälzte die Mehrkosten auf die Kunden ab.","translation":"The company shifted the additional costs onto the customers."},{"sentence":"Er versuchte, die Schuld auf seine Kollegen abzuwälzen.","translation":"He tried to shift the blame onto his colleagues."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Unbeteiligt'' means?","options":["uninvolved","neutral","unrelated","unaffected"],"correctAnswer":"uninvolved"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Negative externalities arise when the costs of an economic activity are shifted onto uninvolved third parties.","options":["Negative externe Effekte entstehen, wenn die Kosten einer wirtschaftlichen Aktivität auf unbeteiligte Dritte abgewälzt werden.","Externe Effekte entstehen, wenn andere die Kosten tragen.","Wenn Dritte die Kosten tragen, entstehen externe Effekte.","Negative Externalitäten verursachen Marktversagen."],"correctAnswer":"Negative externe Effekte entstehen, wenn die Kosten einer wirtschaftlichen Aktivität auf unbeteiligte Dritte abgewälzt werden."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Das Unternehmen wälzte die Mehrkosten auf die Kunden ___.","options":["ab","um","auf","weiter"],"correctAnswer":"ab"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: He tried to shift the blame onto his colleagues","wordBankItems":["Er","versuchte",",","die","Schuld","auf","seine","Kollegen","abzuwälzen","."],"correctAnswer":"Er versuchte , die Schuld auf seine Kollegen abzuwälzen ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Die Unterversorgung'' means?","options":["undersupply","shortage","deficit","lack"],"correctAnswer":"undersupply"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000001c7',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss tax policy at B2","Use Steuerpolitik vocabulary","Talk about tax systems and reform"],"explanation":{"intro":"Tax policy vocabulary covers tax systems, reform, and fiscal policy at B2.","culturalNote":"Germany has a complex Steuersystem: Einkommensteuer (income tax — progressive, up to 45%), Körperschaftsteuer (corporate tax — 15%), Gewerbesteuer (trade tax — varies), Mehrwertsteuer (VAT — 19%/7%). Key issues: Steuervermeidung (tax avoidance), Steuerhinterziehung (tax evasion — illegal), Steueroase (tax haven), Schuldenbremse (debt brake — constitutional rule limiting deficit). Germany runs the Finanzausgleich (fiscal equalisation between states)."},"examples":[{"german":"Progressive Einkommensteuer bedeutet, dass höhere Einkommen prozentual stärker besteuert werden als niedrige.","english":"Progressive income tax means that higher incomes are taxed proportionally more heavily than lower ones."},{"german":"Die Unterscheidung zwischen legaler Steuervermeidung und illegaler Steuerhinterziehung ist für die Rechtspraxis zentral.","english":"The distinction between legal tax avoidance and illegal tax evasion is central to legal practice."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss tax systems, tax avoidance, and fiscal policy at B2."}}',
'{"items":[{"word":"progressiv","translation":"progressive","pronunciation":"pro-greh-SEEF","example":"Progressive Steuer."},{"word":"besteuern","translation":"to tax","pronunciation":"beh-SHTOY-ern","example":"Einkommen besteuern."},{"word":"die Steuervermeidung","translation":"tax avoidance","pronunciation":"dee SHTOY-er-fer-my-doong","example":"Steuervermeidung."},{"word":"die Steuerhinterziehung","translation":"tax evasion","pronunciation":"dee SHTOY-er-hin-ter-tsee-oong","example":"Steuerhinterziehung."},{"word":"prozentual","translation":"proportionally/percentage-wise","pronunciation":"pro-tsen-too-AHL","example":"Prozentual stärker."},{"word":"die Rechtspraxis","translation":"legal practice","pronunciation":"dee REKHTS-prak-sis","example":"Zentral für die Rechtspraxis."}]}',
'{"title":"Prozentual — proportionally (percentage terms)","pattern":"prozentual + comparative = proportionally (more/less in percentage terms)","explanation":"Prozentual = in percentage terms, proportionally. Höhere Einkommen werden prozentual stärker besteuert = Higher incomes are taxed proportionally more. Compare: verhältnismäßig (proportionally — broader, not just percentages), anteilig (in proportion — shares/allocation), relativ (relatively — general comparison). Prozentual is precise: it specifically means the percentage rate, not just a general comparison. Prozentualer Anstieg = percentage increase. Prozentualer Anteil = percentage share.","examples":[{"sentence":"Frauen verdienen in Deutschland prozentual weniger als Männer in vergleichbaren Positionen.","translation":"Women in Germany earn proportionally less than men in comparable positions."},{"sentence":"Die Ausgaben sind prozentual zum Vorjahr gestiegen.","translation":"Expenditure has risen in percentage terms compared to the previous year."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Steuervermeidung'' means?","options":["tax avoidance","tax evasion","tax reduction","tax planning"],"correctAnswer":"tax avoidance"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Progressive income tax means that higher incomes are taxed proportionally more heavily than lower ones.","options":["Progressive Einkommensteuer bedeutet, dass höhere Einkommen prozentual stärker besteuert werden als niedrige.","Progressive Steuer belastet Reiche stärker als Arme.","Wer mehr verdient, zahlt mehr Steuern.","Hohe Einkommen werden höher besteuert."],"correctAnswer":"Progressive Einkommensteuer bedeutet, dass höhere Einkommen prozentual stärker besteuert werden als niedrige."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Frauen verdienen in Deutschland prozentual ___ als Männer.","options":["weniger","mehr","anders","gleich"],"correctAnswer":"weniger"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Expenditure has risen in percentage terms compared to the previous year","wordBankItems":["Die","Ausgaben","sind","prozentual","zum","Vorjahr","gestiegen","."],"correctAnswer":"Die Ausgaben sind prozentual zum Vorjahr gestiegen ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Besteuern'' means?","options":["to tax","to levy","to charge","to impose"],"correctAnswer":"to tax"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000001c8',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss corporate law at B2","Use Unternehmensrecht vocabulary","Talk about business structures and compliance"],"explanation":{"intro":"Corporate law vocabulary covers business forms, liability, and compliance at B2.","culturalNote":"Key German company forms: GmbH (Gesellschaft mit beschränkter Haftung — limited liability company — most common), AG (Aktiengesellschaft — public limited company — stock exchange), GbR (Gesellschaft bürgerlichen Rechts — general partnership), KG (Kommanditgesellschaft — limited partnership). Key concepts: Haftung (liability), Insolvenz (insolvency), Compliance (compliance — increasingly important), Mitbestimmung (codetermination — employee representation on supervisory boards)."},"examples":[{"german":"Die GmbH ist die in Deutschland am häufigsten gewählte Rechtsform, da sie die Haftung der Gesellschafter beschränkt.","english":"The GmbH is the most frequently chosen legal form in Germany, as it limits the liability of the shareholders."},{"german":"Corporate Compliance bezeichnet die Einhaltung aller gesetzlichen Vorschriften und internen Richtlinien im Unternehmen.","english":"Corporate compliance denotes the observance of all legal regulations and internal guidelines in the company."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss corporate law, business forms, and compliance at B2."}}',
'{"items":[{"word":"die Haftung","translation":"liability","pronunciation":"dee HAF-toong","example":"Haftung beschränken."},{"word":"beschränken","translation":"to limit/restrict","pronunciation":"beh-SHREN-ken","example":"Haftung beschränken."},{"word":"die Rechtsform","translation":"legal form","pronunciation":"dee REKHTS-form","example":"Rechtsform wählen."},{"word":"die Einhaltung","translation":"observance/compliance","pronunciation":"dee YN-hal-toong","example":"Einhaltung der Vorschriften."},{"word":"die Richtlinie","translation":"guideline/directive","pronunciation":"dee RIKHT-lee-nee-eh","example":"Interne Richtlinien."},{"word":"der Gesellschafter","translation":"shareholder/partner","pronunciation":"dayr geh-ZEL-shaf-ter","example":"Gesellschafter."}]}',
'{"title":"Bezeichnen — to denote, describe, refer to as","pattern":"etwas bezeichnet X = X denotes/means (definitional statement); als X bezeichnet werden = to be referred to as X","explanation":"Bezeichnen has two uses: (1) etwas bezeichnet X = something denotes/means X (definitional — the thing defines or refers to the concept). Corporate Compliance bezeichnet die Einhaltung = Corporate compliance denotes the observance. (2) als X bezeichnet werden = to be referred to/described as X. Er wird als Experte bezeichnet = He is referred to as an expert. Compare: nennen (to call/name — less formal), definieren als (to define as — more technical/precise), heißen (to be called — simpler).","examples":[{"sentence":"Der Begriff ''Nachhaltigkeit'' bezeichnet ein breites Konzept aus Ökologie, Ökonomie und Sozialem.","translation":"The term ''sustainability'' denotes a broad concept encompassing ecology, economics, and the social sphere."},{"sentence":"Diese Methode wird oft als ''Best Practice'' bezeichnet.","translation":"This method is often referred to as ''best practice''."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Haftung'' means?","options":["liability","responsibility","obligation","accountability"],"correctAnswer":"liability"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The GmbH is the most frequently chosen legal form in Germany, as it limits the liability of the shareholders.","options":["Die GmbH ist die in Deutschland am häufigsten gewählte Rechtsform, da sie die Haftung der Gesellschafter beschränkt.","Die GmbH ist beliebt, weil die Haftung begrenzt ist.","In Deutschland wählen viele Unternehmen die GmbH.","Die GmbH beschränkt die Gesellschafterhaftung."],"correctAnswer":"Die GmbH ist die in Deutschland am häufigsten gewählte Rechtsform, da sie die Haftung der Gesellschafter beschränkt."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Der Begriff ''Nachhaltigkeit'' bezeichnet ein breites Konzept aus Ökologie, Ökonomie und ___.","options":["Sozialem","Gesellschaft","Gesellschaftlichem","dem Sozialen"],"correctAnswer":"Sozialem"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: This method is often referred to as best practice","wordBankItems":["Diese","Methode","wird","oft","als","Best","Practice","bezeichnet","."],"correctAnswer":"Diese Methode wird oft als Best Practice bezeichnet ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Die Einhaltung'' means?","options":["observance/compliance","adherence","keeping","following"],"correctAnswer":"observance/compliance"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000001c9',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss labour law at B2","Use Arbeitsrecht vocabulary","Talk about employment and worker rights"],"explanation":{"intro":"Labour law vocabulary covers employment contracts, worker rights, and termination at B2.","culturalNote":"Germany has strong Arbeitsrecht (labour law): Kündigungsschutz (protection against unfair dismissal — KSchG), Betriebsrat (works council — employee representation at company level), Tarifvertrag (collective agreement), Mindestlohn (minimum wage — currently €12+/hour). Arbeitsgericht (labour court) resolves disputes. Mitbestimmung (codetermination) gives employees board representation in large companies (Mitbestimmungsgesetz 1976)."},"examples":[{"german":"Der Kündigungsschutz bewahrt Arbeitnehmer vor willkürlichen Entlassungen und verlangt sachliche Kündigungsgründe.","english":"Protection against unfair dismissal protects employees from arbitrary dismissals and requires substantive grounds for termination."},{"german":"Der Betriebsrat hat weitreichende Mitwirkungs- und Mitbestimmungsrechte in sozialen und personellen Angelegenheiten.","english":"The works council has far-reaching rights of participation and co-determination in social and personnel matters."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss labour law, worker rights, and works councils at B2."}}',
'{"items":[{"word":"der Kündigungsschutz","translation":"protection against unfair dismissal","pronunciation":"dayr KÜN-di-goonks-shoots","example":"Kündigungsschutz."},{"word":"sachlich","translation":"substantive/factual/objective","pronunciation":"ZAKH-likh","example":"Sachlicher Grund."},{"word":"weitreichend","translation":"far-reaching","pronunciation":"VYT-ry-khend","example":"Weitreichende Rechte."},{"word":"die Mitwirkung","translation":"participation/having a say","pronunciation":"dee MIT-vir-koong","example":"Mitwirkungsrechte."},{"word":"personell","translation":"personnel/staffing","pronunciation":"per-zo-NEL","example":"Personelle Angelegenheiten."},{"word":"bewahren vor","translation":"to protect from/guard against","pronunciation":"beh-VAH-ren for","example":"Vor Entlassung bewahren."}]}',
'{"title":"Bewahren vor — to protect from, preserve from","pattern":"jemanden vor + dative bewahren = to protect, guard, preserve from (prevent something bad happening)","explanation":"Bewahren vor + dative = to protect from, guard against, preserve from. Das Gesetz bewahrt Arbeitnehmer vor Willkür = The law protects employees from arbitrariness. Perfect: hat bewahrt. Jemanden vor etwas bewahren = to protect someone from something. Compare: schützen vor (to protect from — more general, more common everyday), retten vor (to save from — implies immediate danger), hüten vor (to guard from — more archaic/poetic). Bewahren often implies something that was at risk of being lost or harmed.","examples":[{"sentence":"Impfungen bewahren uns vor gefährlichen Infektionskrankheiten.","translation":"Vaccinations protect us from dangerous infectious diseases."},{"sentence":"Eine gute Vorbereitung bewahrt Sie vor unangenehmen Überraschungen.","translation":"Good preparation will protect you from unpleasant surprises."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Sachlich'' in ''sachliche Kündigungsgründe'' means?","options":["substantive/objective","material","reasonable","factual"],"correctAnswer":"substantive/objective"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Protection against unfair dismissal protects employees from arbitrary dismissals and requires substantive grounds for termination.","options":["Der Kündigungsschutz bewahrt Arbeitnehmer vor willkürlichen Entlassungen und verlangt sachliche Kündigungsgründe.","Arbeitnehmer sind durch das Arbeitsrecht geschützt.","Willkürliche Kündigungen sind durch Kündigungsschutz verboten.","Kündigungsschutz schützt vor ungerechtfertigten Entlassungen."],"correctAnswer":"Der Kündigungsschutz bewahrt Arbeitnehmer vor willkürlichen Entlassungen und verlangt sachliche Kündigungsgründe."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Impfungen bewahren uns vor gefährlichen ___.","options":["Infektionskrankheiten","Infektionen","Krankheiten","Viren"],"correctAnswer":"Infektionskrankheiten"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Good preparation will protect you from unpleasant surprises","wordBankItems":["Eine","gute","Vorbereitung","bewahrt","Sie","vor","unangenehmen","Überraschungen","."],"correctAnswer":"Eine gute Vorbereitung bewahrt Sie vor unangenehmen Überraschungen ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Weitreichend'' means?","options":["far-reaching","wide-ranging","extensive","broad"],"correctAnswer":"far-reaching"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000001ca',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss collective bargaining at B2","Use Tarifverhandlung vocabulary","Talk about unions and wage agreements"],"explanation":{"intro":"Collective bargaining vocabulary covers wage negotiations, unions, and industrial relations at B2.","culturalNote":"Germany''s Tarifautonomie (collective bargaining autonomy — constitutionally protected) means unions (Gewerkschaften — DGB, IG Metall, ver.di) and employer associations (Arbeitgeberverbände) negotiate collectively. Tarifflucht (fleeing collective agreements) by employers is controversial. Streik (strike) is a constitutional right (Art. 9 GG). The Tarifeinheitsgesetz (Collective Agreement Unity Act) regulates competing unions."},"examples":[{"german":"Tarifverhandlungen zwischen Gewerkschaften und Arbeitgebern legen Löhne, Arbeitszeiten und weitere Arbeitsbedingungen fest.","english":"Collective bargaining negotiations between unions and employers establish wages, working hours, and further working conditions."},{"german":"Das Streikrecht ist ein grundlegendes Instrument der Gewerkschaften, um Druck auf die Arbeitgeberseite auszuüben.","english":"The right to strike is a fundamental instrument of the trade unions for exerting pressure on the employers'' side."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss collective bargaining, strikes, and trade union rights at B2."}}',
'{"items":[{"word":"festlegen","translation":"to establish/set/determine","pronunciation":"FEST-lay-gen","example":"Löhne festlegen."},{"word":"das Streikrecht","translation":"right to strike","pronunciation":"dahs SHTRYK-rekht","example":"Streikrecht."},{"word":"ausüben","translation":"to exert/exercise","pronunciation":"OWS-ü-ben","example":"Druck ausüben."},{"word":"die Arbeitgeberseite","translation":"employers'' side","pronunciation":"dee AR-byt-gay-ber-zy-teh","example":"Arbeitgeberseite."},{"word":"die Arbeitsbedingung","translation":"working condition","pronunciation":"dee AR-byts-beh-ding-oong","example":"Arbeitsbedingungen."},{"word":"grundlegend","translation":"fundamental/basic","pronunciation":"GROONT-lay-gend","example":"Grundlegendes Instrument."}]}',
'{"title":"Druck ausüben auf — to exert pressure on","pattern":"Druck ausüben auf + accusative = to exert pressure on (separable idiom)","explanation":"Druck ausüben auf + accusative = to exert pressure on. Die Gewerkschaft übt Druck auf die Arbeitgeber aus = The union exerts pressure on the employers. Separable: übt...aus. Perfect: hat Druck ausgeübt. Related: unter Druck setzen (to put under pressure — implies coercion), unter Druck stehen (to be under pressure — state), Druck machen (to apply pressure — colloquial). In formal/political context: politischen Druck ausüben (to exert political pressure).","examples":[{"sentence":"Internationale Organisationen üben Druck auf die Regierung aus, die Menschenrechte zu achten.","translation":"International organisations exert pressure on the government to respect human rights."},{"sentence":"Die Verbraucher können durch gezielte Boykotte Druck auf Unternehmen ausüben.","translation":"Consumers can exert pressure on companies through targeted boycotts."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Festlegen'' means?","options":["to establish/set/determine","to fix","to determine","to lay down"],"correctAnswer":"to establish/set/determine"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The right to strike is a fundamental instrument of the trade unions for exerting pressure on the employers'' side.","options":["Das Streikrecht ist ein grundlegendes Instrument der Gewerkschaften, um Druck auf die Arbeitgeberseite auszuüben.","Gewerkschaften können streiken, um Druck auszuüben.","Das Streikrecht schützt Arbeitnehmer.","Gewerkschaften setzen Arbeitgeber unter Druck."],"correctAnswer":"Das Streikrecht ist ein grundlegendes Instrument der Gewerkschaften, um Druck auf die Arbeitgeberseite auszuüben."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Internationale Organisationen üben Druck auf die Regierung ___, die Menschenrechte zu achten.","options":["aus","an","auf","ab"],"correctAnswer":"aus"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Consumers can exert pressure on companies through targeted boycotts","wordBankItems":["Die","Verbraucher","können","durch","gezielte","Boykotte","Druck","auf","Unternehmen","ausüben","."],"correctAnswer":"Die Verbraucher können durch gezielte Boykotte Druck auf Unternehmen ausüben ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Grundlegend'' means?","options":["fundamental/basic","essential","primary","underlying"],"correctAnswer":"fundamental/basic"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000001cb',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss corporate culture at B2","Use Unternehmenskultur vocabulary","Talk about values and organisational dynamics"],"explanation":{"intro":"Corporate culture vocabulary covers values, norms, and organisational behaviour at B2.","culturalNote":"Unternehmenskultur (corporate culture) emerged as a management concept in the 1980s. Key elements: Mission Statement, Kernwerte (core values), Führungsstil (leadership style — autoritär, kooperativ, transformational). Germany has a strong tradition of Mitbestimmung (codetermination) which shapes culture. Work-life balance: Germany has strong legal protections (Urlaubsanspruch — holiday entitlement, Arbeitszeitgesetz — working hours law)."},"examples":[{"german":"Eine gelebte Unternehmenskultur, die auf Vertrauen und offener Kommunikation basiert, steigert Mitarbeiterzufriedenheit und Produktivität.","english":"A lived corporate culture based on trust and open communication increases employee satisfaction and productivity."},{"german":"Kulturwandel in Organisationen scheitert häufig daran, dass Veränderungen von oben verordnet statt von unten gelebt werden.","english":"Cultural change in organisations often fails because changes are decreed from above rather than lived from below."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss corporate culture, values, and organisational change at B2."}}',
'{"items":[{"word":"gelebt","translation":"lived (authentic, practised)","pronunciation":"geh-LAYPT","example":"Gelebte Kultur."},{"word":"scheitern an","translation":"to fail due to/because of","pronunciation":"SHYT-ern an","example":"Scheitern an Problemen."},{"word":"verordnen","translation":"to decree/prescribe","pronunciation":"fer-ORD-nen","example":"Von oben verordnen."},{"word":"die Mitarbeiterzufriedenheit","translation":"employee satisfaction","pronunciation":"dee MIT-ar-by-ter-tsoo-free-den-hyt","example":"Mitarbeiterzufriedenheit."},{"word":"steigern","translation":"to increase/boost","pronunciation":"SHTEY-gern","example":"Produktivität steigern."},{"word":"basieren auf","translation":"to be based on","pronunciation":"bah-ZEER-en owf","example":"Auf Vertrauen basieren."}]}',
'{"title":"Scheitern an — to fail because of / due to","pattern":"etwas scheitert an + dative = something fails because of, founders on","explanation":"Scheitern an + dative = to fail because of, to founder on. Der Plan scheiterte an der Finanzierung = The plan failed due to financing. Das Projekt scheiterte am Widerstand = The project foundered on resistance. Perfect: ist gescheitert (sein-verb). Das Scheitern = failure. Note: scheitern always takes sein in perfect (not haben). Common in formal analysis. Compare: fehlschlagen (to fail — more about a plan or attempt that doesn''t work), misslingen (to fail — more about a task or performance going wrong), versagen (to fail — often about a person or system).","examples":[{"sentence":"Die Reform scheiterte am Widerstand der Lobbygruppen.","translation":"The reform failed due to resistance from lobby groups."},{"sentence":"Das Gespräch scheiterte an gegenseitigem Misstrauen.","translation":"The conversation failed due to mutual mistrust."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Gelebt'' in ''gelebte Kultur'' means?","options":["lived (authentic, practised)","lived (biographical)","experienced","real"],"correctAnswer":"lived (authentic, practised)"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Cultural change in organisations often fails because changes are decreed from above rather than lived from below.","options":["Kulturwandel in Organisationen scheitert häufig daran, dass Veränderungen von oben verordnet statt von unten gelebt werden.","Kulturwandel scheitert an mangelnder Unterstützung von unten.","Top-down-Veränderungen scheitern oft.","Organisationskultur lässt sich nicht verordnen."],"correctAnswer":"Kulturwandel in Organisationen scheitert häufig daran, dass Veränderungen von oben verordnet statt von unten gelebt werden."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Die Reform scheiterte am Widerstand der ___.","options":["Lobbygruppen","Lobbyisten","Interessengruppen","Interessenvertreter"],"correctAnswer":"Lobbygruppen"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The conversation failed due to mutual mistrust","wordBankItems":["Das","Gespräch","scheiterte","an","gegenseitigem","Misstrauen","."],"correctAnswer":"Das Gespräch scheiterte an gegenseitigem Misstrauen ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Verordnen'' means?","options":["to decree/prescribe","to order","to mandate","to impose"],"correctAnswer":"to decree/prescribe"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-0000000001cc',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss leadership and management at B2","Use Führung vocabulary","Talk about leadership styles and teams"],"explanation":{"intro":"Leadership and management vocabulary covers leadership styles, motivation, and team dynamics at B2.","culturalNote":"German Führungsstile (leadership styles): autoritär (authoritarian), demokratisch (democratic), kooperativ (cooperative — dominant in Germany), transformational (transformational — inspiring vision). Key concepts: Motivation (Maslow-Bedürfnishierarchie well-known), Delegation, Empowerment, Feedback. Germans value Pünktlichkeit (punctuality), Gründlichkeit (thoroughness), and Verlässlichkeit (reliability) in leaders."},"examples":[{"german":"Transformationale Führung setzt auf eine inspirierende Vision, die Mitarbeiter intrinsisch motiviert und zur Höchstleistung anspornt.","english":"Transformational leadership relies on an inspiring vision that intrinsically motivates employees and spurs them on to peak performance."},{"german":"Effektive Führungskräfte verstehen es, individuelle Stärken ihrer Teammitglieder zu erkennen und gezielt einzusetzen.","english":"Effective leaders understand how to identify the individual strengths of their team members and to deploy them in a targeted manner."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss leadership styles, motivation, and management at B2."}}',
'{"items":[{"word":"anspornen","translation":"to spur on/motivate","pronunciation":"AN-shpor-nen","example":"Zu Höchstleistung anspornen."},{"word":"intrinsisch","translation":"intrinsic","pronunciation":"in-TRIN-zish","example":"Intrinsisch motiviert."},{"word":"die Höchstleistung","translation":"peak performance","pronunciation":"dee HÖKHST-lys-toong","example":"Höchstleistung."},{"word":"gezielt","translation":"in a targeted manner","pronunciation":"geh-TSEELT","example":"Gezielt einsetzen."},{"word":"einsetzen","translation":"to deploy/use","pronunciation":"YN-zetsen","example":"Stärken einsetzen."},{"word":"verstehen","translation":"to understand how to (can mean to know how)","pronunciation":"fer-SHTAY-en","example":"Verstehen zu."}]}',
'{"title":"Verstehen zu + Infinitiv — to know how to, to understand how to","pattern":"jemand versteht es, etwas zu tun = someone knows how to do something (implies skill/art)","explanation":"Verstehen + zu + Infinitiv (often with es): versteht es, zu + Inf = knows how to, understands how to, has the art of. Effective leaders understand how to identify strengths = Effektive Führungskräfte verstehen es, Stärken zu erkennen. This construction implies mastery or skill, not just capability. Compare: können (to be able to — simple ability), wissen wie man (to know how — more literal knowledge), es fertigbringen zu (to manage to — often implies difficulty overcome).","examples":[{"sentence":"Sie versteht es, komplizierte Sachverhalte einfach zu erklären.","translation":"She understands how to explain complicated matters simply."},{"sentence":"Er versteht es, Menschen für seine Ideen zu begeistern.","translation":"He knows how to enthuse people for his ideas."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Anspornen'' means?","options":["to spur on/motivate","to encourage","to drive","to push"],"correctAnswer":"to spur on/motivate"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Effective leaders understand how to identify the individual strengths of their team members and to deploy them in a targeted manner.","options":["Effektive Führungskräfte verstehen es, individuelle Stärken ihrer Teammitglieder zu erkennen und gezielt einzusetzen.","Gute Führungskräfte erkennen die Stärken ihrer Mitarbeiter.","Effektive Führung bedeutet, Stärken gezielt einzusetzen.","Führungskräfte müssen Stärken ihrer Teams kennen."],"correctAnswer":"Effektive Führungskräfte verstehen es, individuelle Stärken ihrer Teammitglieder zu erkennen und gezielt einzusetzen."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Sie versteht es, komplizierte Sachverhalte einfach zu ___.","options":["erklären","erklärt","erklärend","erkläre"],"correctAnswer":"erklären"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: He knows how to enthuse people for his ideas","wordBankItems":["Er","versteht","es",",","Menschen","für","seine","Ideen","zu","begeistern","."],"correctAnswer":"Er versteht es , Menschen für seine Ideen zu begeistern ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Gezielt'' means?","options":["in a targeted manner","deliberately","purposefully","specifically"],"correctAnswer":"in a targeted manner"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

